ST.xhtml:p:
(*(*心跳包，写入0x3A，保证使能*)(*3.10老版BM115E调焦程序*)
g_noHeart_Beat := 58;

R_Trigger(CLK := g_bF050Home );
(*R_Trigger1(CLK := g_bFBM11XEnable OR g_bMnualAnalogEnable);*)

(*回零,F轴到0刻度*)
IF R_Trigger.Q THEN
  g_bF050Home := false; 
  g_noPositionSetFocus := 0;   
END_IF;

IF g_bFBM115EEnable THEN
  dFPosFb := g_dAnalogPosition;
  g_bFBM115EEnable := FALSE;
  g_bFocusEnable := FALSE;
  nState := 5;
ELSIF g_bMnualAnalogEnable THEN
  dFPosFb := g_dMnualAnalogPosition;
  g_bMnualAnalogEnable := FALSE;
  nState := 5;
END_IF;

CASE nState OF
  0:
    nState := 0;
  5:  (*步进电机调焦*)
    g_noPositionSetFocus := LREAL_TO_DINT(1000.0*dFPosFb);
    nState := 10;      
  10:(*调焦完成*)
    IF g_niBM115EActualFocus>DINT_TO_INT(g_noPositionSetFocus)-50 AND g_niBM115EActualFocus< DINT_TO_INT(g_noPositionSetFocus)+50 THEN
      g_bFocusDone := TRUE;
      nState := 0;
    END_IF;
END_CASE;    

(*温度转换1:0.01°*)
(*坐标反馈*)
g_dFaxisAnoagePosFb := INT_TO_LREAL(g_niBM115EActualFocus/1000);
(*ECAT通信状态，0异常，1正常*)
IF g_niBM115EStatusEnable = 1 THEN
  g_Alarm.alarmArray[357] := 0;  
ELSE
  g_Alarm.alarmArray[357] := 1085;  
END_IF;  
(*上保护镜温度报警*)
IF g_niBM115ETopProtectiveWindowTemperAlarm = 1 THEN
  g_Alarm.alarmArray[358] := 0;  
ELSE
  g_Alarm.alarmArray[358] := 1086;  
END_IF; 
(*腔体温度报警*)
IF g_niBM115ECavityTemperatureAlarm = 1 THEN
  g_Alarm.alarmArray[359] := 0;  
ELSE
  g_Alarm.alarmArray[359] := 1087;  
END_IF;
(*下保护镜温度报警*)  
IF g_niBM115EBottomProtectiveWindowTemperAlarm = 1 THEN
  g_Alarm.alarmArray[360] := 0;  
ELSE
  g_Alarm.alarmArray[360] := 1088;  
END_IF; 
(*电机故障代码*)  
IF g_niBM115EFocusMotorErrorCode <>0 THEN
  g_Alarm.alarmArray[361] := 1089;  
ELSE
  g_Alarm.alarmArray[361] := 0;  
END_IF; 
(*调焦头WIFI报警*)  
IF g_niBM115EStatusWIFI = 1 THEN
  g_Alarm.alarmArray[362] := 0;  
ELSE
  g_Alarm.alarmArray[362] := 1090;  
END_IF;
